/* Intrusive, external diagnostic for a newly created owned x64 child only.
   No system profiling, process injection, symbols downloads or settings changes.
   Sample times include suspension overhead and are not latency acceptance. */
#define WIN32_LEAN_AND_MEAN
#define NOMINMAX
#include <windows.h>
#include <dbghelp.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <wchar.h>

#define MAX_SAMPLES 4096
#define MAX_FRAMES 40
typedef struct sample {
 LONGLONG begin,end;
 uint64_t thread_kernel,thread_user,process_kernel,process_user;
 DWORD previous_suspend,context_error,resume_error;
 unsigned depth;DWORD64 frames[MAX_FRAMES];
} sample;
static LONGLONG tick(void){LARGE_INTEGER value;QueryPerformanceCounter(&value);return value.QuadPart;}
static uint64_t ft(FILETIME value){return (uint64_t)value.dwHighDateTime<<32|value.dwLowDateTime;}
static void string(const char *s){putchar('"');for(;*s;++s){unsigned char c=(unsigned char)*s;
 if(c=='"'||c=='\\')printf("\\%c",c);else if(c<32)printf("\\u%04x",c);else putchar(c);}putchar('"');}
static void times(HANDLE handle,int thread,uint64_t *kernel,uint64_t *user){
 FILETIME c,e,k,u;BOOL ok=thread?GetThreadTimes(handle,&c,&e,&k,&u):GetProcessTimes(handle,&c,&e,&k,&u);
 *kernel=ok?ft(k):0;*user=ok?ft(u):0;
}
int wmain(int argc,wchar_t **argv){
 if(argc!=4 || wcschr(argv[1],L'"') || wcschr(argv[2],L'"'))return 2;
 sample *samples=calloc(MAX_SAMPLES,sizeof(*samples));if(!samples)return 3;
 SECURITY_ATTRIBUTES security={sizeof(security),NULL,TRUE};
 HANDLE output=CreateFileW(argv[3],GENERIC_WRITE,FILE_SHARE_READ,&security,CREATE_NEW,FILE_ATTRIBUTE_NORMAL,NULL);
 if(output==INVALID_HANDLE_VALUE){fprintf(stderr,"Create owned child log: %lu\n",GetLastError());free(samples);return 4;}
 HANDLE input=CreateFileW(L"NUL",GENERIC_READ,FILE_SHARE_READ|FILE_SHARE_WRITE,&security,OPEN_EXISTING,0,NULL);
 STARTUPINFOEXW startup={0};startup.StartupInfo.cb=sizeof(startup);startup.StartupInfo.dwFlags=STARTF_USESTDHANDLES;
 startup.StartupInfo.hStdOutput=startup.StartupInfo.hStdError=output;startup.StartupInfo.hStdInput=input;
 SIZE_T size=0;InitializeProcThreadAttributeList(NULL,1,0,&size);
 startup.lpAttributeList=HeapAlloc(GetProcessHeap(),0,size);
 HANDLE inherited[]={output,input};BOOL attrs=FALSE;PROCESS_INFORMATION child={0};
 wchar_t command[32768];_snwprintf_s(command,32768,_TRUNCATE,L"\"%s\" \"%s\"",argv[1],argv[2]);
 if(input==INVALID_HANDLE_VALUE || !startup.lpAttributeList || !InitializeProcThreadAttributeList(startup.lpAttributeList,1,0,&size))goto failed;
 attrs=TRUE;
 if(!UpdateProcThreadAttribute(startup.lpAttributeList,0,PROC_THREAD_ATTRIBUTE_HANDLE_LIST,inherited,sizeof(inherited),NULL,NULL))goto failed;
 if(!CreateProcessW(argv[1],command,NULL,NULL,TRUE,CREATE_SUSPENDED|EXTENDED_STARTUPINFO_PRESENT,NULL,NULL,&startup.StartupInfo,&child))goto failed;
 DeleteProcThreadAttributeList(startup.lpAttributeList);HeapFree(GetProcessHeap(),0,startup.lpAttributeList);attrs=FALSE;startup.lpAttributeList=NULL;
 CloseHandle(input);input=INVALID_HANDLE_VALUE;CloseHandle(output);output=INVALID_HANDLE_VALUE;
 SymSetOptions(SYMOPT_DEFERRED_LOADS|SYMOPT_UNDNAME|SYMOPT_FAIL_CRITICAL_ERRORS|SYMOPT_NO_PROMPTS|SYMOPT_IGNORE_NT_SYMPATH|SYMOPT_DISABLE_SYMSRV_AUTODETECT);
 BOOL symbols=SymInitializeW(child.hProcess,L"D:\\NexaUI\\build\\Release",TRUE);
 DWORD symbols_error=symbols?0:GetLastError();LARGE_INTEGER frequency;QueryPerformanceFrequency(&frequency);
 LONGLONG started=tick();unsigned count=0;BOOL timeout=FALSE;
 if(ResumeThread(child.hThread)==(DWORD)-1){TerminateProcess(child.hProcess,90);WaitForSingleObject(child.hProcess,5000);goto failed;}
 while(WaitForSingleObject(child.hProcess,5)==WAIT_TIMEOUT){
  if(tick()-started>30*frequency.QuadPart || count==MAX_SAMPLES){timeout=TRUE;TerminateProcess(child.hProcess,91);WaitForSingleObject(child.hProcess,5000);break;}
  if(symbols && count%4==0)(void)SymRefreshModuleList(child.hProcess);
  sample *s=&samples[count++];s->begin=tick();
  s->previous_suspend=SuspendThread(child.hThread);
  if(s->previous_suspend!=(DWORD)-1){
   CONTEXT context={0};context.ContextFlags=CONTEXT_FULL;
   if(GetThreadContext(child.hThread,&context)){
    s->frames[s->depth++]=context.Rip;
    STACKFRAME64 frame={0};frame.AddrPC.Offset=context.Rip;frame.AddrStack.Offset=context.Rsp;frame.AddrFrame.Offset=context.Rbp;
    frame.AddrPC.Mode=frame.AddrStack.Mode=frame.AddrFrame.Mode=AddrModeFlat;
    if(symbols)for(unsigned i=0;i<MAX_FRAMES-1;++i){
     if(!StackWalk64(IMAGE_FILE_MACHINE_AMD64,child.hProcess,child.hThread,&frame,&context,NULL,SymFunctionTableAccess64,SymGetModuleBase64,NULL)||!frame.AddrPC.Offset)break;
     if(frame.AddrPC.Offset==s->frames[s->depth-1])continue;
     s->frames[s->depth++]=frame.AddrPC.Offset;
    }
   }else s->context_error=GetLastError();
   times(child.hThread,1,&s->thread_kernel,&s->thread_user);times(child.hProcess,0,&s->process_kernel,&s->process_user);
   if(ResumeThread(child.hThread)==(DWORD)-1)s->resume_error=GetLastError();
  }else s->context_error=GetLastError();
  s->end=tick();
 }
 DWORD exit=0;GetExitCodeProcess(child.hProcess,&exit);uint64_t tk,tu,pk,pu;
 times(child.hThread,1,&tk,&tu);times(child.hProcess,0,&pk,&pu);
 printf("{\"schema\":1,\"intrusive\":true,\"pid\":%lu,\"tid\":%lu,\"frequency\":%lld,\"started\":%lld,\"exit\":%lu,\"timeout\":%s,\"symbols_error\":%lu,\"thread_kernel_100ns\":%llu,\"thread_user_100ns\":%llu,\"process_kernel_100ns\":%llu,\"process_user_100ns\":%llu,\"samples\":[\n",child.dwProcessId,child.dwThreadId,frequency.QuadPart,started,exit,timeout?"true":"false",symbols_error,tk,tu,pk,pu);
 for(unsigned i=0;i<count;++i){sample *s=&samples[i];printf("%s{\"begin\":%lld,\"end\":%lld,\"previous_suspend\":%lu,\"context_error\":%lu,\"resume_error\":%lu,\"thread_kernel_100ns\":%llu,\"thread_user_100ns\":%llu,\"process_kernel_100ns\":%llu,\"process_user_100ns\":%llu,\"frames\":[",i?",":"",s->begin,s->end,s->previous_suspend,s->context_error,s->resume_error,s->thread_kernel,s->thread_user,s->process_kernel,s->process_user);
  for(unsigned j=0;j<s->depth;++j)printf("%s\"%016llx\"",j?",":"",s->frames[j]);puts("]}");}
 puts("],\"addresses\":[");unsigned addresses=0;
 for(unsigned i=0;i<count;++i)for(unsigned j=0;j<samples[i].depth;++j){
  DWORD64 address=samples[i].frames[j];BOOL seen=FALSE;
  for(unsigned a=0;a<=i && !seen;++a)for(unsigned b=0;b<(a==i?j:samples[a].depth);++b)if(samples[a].frames[b]==address){seen=TRUE;break;}
  if(seen)continue;
  IMAGEHLP_MODULE64 module={0};module.SizeOfStruct=sizeof(module);
  BOOL found=symbols&&SymGetModuleInfo64(child.hProcess,address,&module);
  char buffer[sizeof(SYMBOL_INFO)+MAX_SYM_NAME]={0};SYMBOL_INFO *symbol=(SYMBOL_INFO *)buffer;
  symbol->SizeOfStruct=sizeof(*symbol);symbol->MaxNameLen=MAX_SYM_NAME;DWORD64 displacement=0;
  BOOL named=symbols&&SymFromAddr(child.hProcess,address,&displacement,symbol);
  printf("%s{\"address\":\"%016llx\",\"module\":",addresses++?",":"",address);string(found?module.ModuleName:"");
  printf(",\"offset\":%llu,\"symbol\":",found?address-module.BaseOfImage:0);string(named?symbol->Name:"");
  printf(",\"symbol_displacement\":%llu}\n",named?displacement:0);
 }
 puts("]}");
 if(symbols)SymCleanup(child.hProcess);CloseHandle(child.hThread);CloseHandle(child.hProcess);free(samples);return timeout||exit?1:0;
failed:
 fprintf(stderr,"Owned child sampler setup failed: %lu\n",GetLastError());
 if(child.hProcess){TerminateProcess(child.hProcess,92);WaitForSingleObject(child.hProcess,5000);CloseHandle(child.hThread);CloseHandle(child.hProcess);}
 if(attrs)DeleteProcThreadAttributeList(startup.lpAttributeList);
 if(startup.lpAttributeList)HeapFree(GetProcessHeap(),0,startup.lpAttributeList);
 if(input!=INVALID_HANDLE_VALUE)CloseHandle(input);if(output!=INVALID_HANDLE_VALUE)CloseHandle(output);free(samples);return 5;
}

