static BOOL WINAPI fault_thread_times(HANDLE thread,FILETIME *c,FILETIME *e,FILETIME *k,FILETIME *u){
 if(GetEnvironmentVariableW(L"R01_FAIL_THREAD_CPU",NULL,0)){SetLastError(ERROR_ACCESS_DENIED);return FALSE;}
 return GetThreadTimes(thread,c,e,k,u);
}
static BOOL WINAPI fault_process_times(HANDLE process,FILETIME *c,FILETIME *e,FILETIME *k,FILETIME *u){
 if(GetEnvironmentVariableW(L"R01_FAIL_PROCESS_CPU",NULL,0)){SetLastError(ERROR_ACCESS_DENIED);return FALSE;}
 return GetProcessTimes(process,c,e,k,u);
}
#define GetThreadTimes fault_thread_times
#define GetProcessTimes fault_process_times
